      de: ["Im Herzen des Stanley Parks gelegen", "Zentrum für Meeresforschung und Rettung", "Erstes öffentliches Aquarium Kanadas", "Über 50.000 Meeresbewohner"],
      ro: ["Situat în celebrul Stanley Park din Vancouver", "Primul acvariu public deschis în Canada (1956)", "Centru de cercetare și reabilitare marină", "Peste 65.000 de animale marine expuse"],
      en: ["Opened in 1956", "Located in Stanley Park", "Canada's first public aquarium", "Focus on marine research"],
      es: ["Situado en el corazón de Stanley Park", "Centro de investigación y rescate marino", "Primer acuario público de Canadá", "Más de 50.000 habitantes marinos"],
      pt: ["Situado no coração do Stanley Park", "Centro de pesquisa e resgate marinho", "Primeiro aquário público do Canadá", "Mais de 50.000 habitantes marinhos"],
      fr: ["Situé au cœur du parc Stanley", "Centre de recherche et de sauvetage marin", "Premier aquarium public du Canada", "Plus de 50 000 habitants marins"],
