    facts: {
      de: ["Über 30 Fahrgeschäfte", "Live-Unterhaltung", "Campingplatz in der Nähe", "Familienfreundlich"],
      hu: ["1982-ben nyílt meg.", "32 különböző játékot és hullámvasutat kínál.", "Szezonálisan, tavasztól őszig üzemel."],
      ro: ["Peste 30 de atracții", "Divertisment live", "Camping în apropiere", "Prielnic pentru familii"],
      en: ["West of Calgary", "More than 30 rides", "Popular summer family destination"],
      es: ["Más de 30 atracciones", "Entretenimiento en vivo", "Zona de camping cercana", "Ideal para familias"],
      pt: ["Mais de 30 brinquedos", "Entretenimento ao vivo", "Área de camping próxima", "Ideal para famílias"],
      fr: ["Plus de 30 manèges", "Spectacles en direct", "Terrain de camping à proximité", "Idéal pour les familles"],
    }, image: "/poi-images/calaway-park-life-v2.webp",
    descriptionAdvanced: {
      de: "Der Calaway Park westlich von Calgary ist der größte Outdoor-Freizeitpark in Westkanada. Seit seiner Eröffnung im Jahr 1982 bietet der Park eine breite Palette an Fahrgeschäften und Attraktionen für alle Altersgruppen, eingebettet in die malerische Kulisse der Rocky Mountains. Mit 32 Fahrgeschäften, darunter Achterbahnen und Wasserbahnen, sowie zahlreichen Live-Shows ist der Park ein zentrales Ziel für Familien in Alberta. Ein besonderes Merkmal ist der nostalgische Charme des Parks und sein Fokus auf kinderfreundliche Erlebnisse. Neben den mechanischen Attraktionen bietet der Park auch einen großen Campingplatz, der ihn zu einem beliebten Ziel für mehrtägige Ausflüge macht. Calaway Park ist saisonal von Mai bis Oktober geöffnet und bleibt trotz moderner Ergänzungen seinen Wurzeln als traditioneller Vergnügungspark treu.",
      hu: "A Calgarytól nyugatra fekvő Calaway Park Nyugat-Kanada legnagyobb szabadtéri vidámparkja. 1982-es megnyitása óta a park a hullámvasutak és attrakciók széles választékát kínálja minden korosztály számára, a Sziklás-hegység festői hátterével övezve. 32 játékkal, köztük hullámvasutakkal és vízi vasutakkal, valamint számos élő show-val a park Alberta családjainak központi célpontja. Különlegessége a park nosztalgikus bája és a gyerekbarát élményekre való összpontosítás. A mechanikus attrakciók mellett a park egy nagy kempinggel is rendelkezik, ami népszerűvé teszi a többnapos kirándulásokhoz. A Calaway Park szezonálisan, májustól októberig tart nyitva, és a modern fejlesztések ellenére hű maradt hagyományos vidámpark gyökereihez.",
      ro: "Calaway Park, situat la vest de Calgary, este cel mai mare parc de distracții în aer liber din vestul Canadei. De la deschiderea sa în 1982, parcul oferă o gamă largă de atracții pentru toate vârstele, având ca fundal peisajul pitoresc al Munților Stâncoși. Cu 32 de atracții, inclusiv roller coastere și tobogane cu apă, precum și numeroase spectacole live, parcul este o destinație centrală pentru familiile din Alberta. O caracteristică distinctivă este farmecul nostalgic al parcului și accentul pus pe experiențele prietenoase pentru copii. Pe lângă atracțiile mecanice, parcul oferă și un camping mare, ceea ce îl face popular pentru excursii de mai multe zile. Calaway Park este deschis sezonier din mai până în octombrie și rămâne fidel rădăcinilor sale de parc tradițional în ciuda adăugirilor moderne.",
      en: "Calaway Park, located west of Calgary, is Western Canada's largest outdoor amusement park. Since opening in 1982, the park has offered a wide range of rides and attractions for all ages, set against the picturesque backdrop of the Rocky Mountains. Featuring 32 rides, including roller coasters and log flumes, as well as numerous live shows, the park is a central destination for families in Alberta. A distinctive feature is the park's nostalgic charm and its focus on kid-friendly experiences. Beyond mechanical attractions, the park also includes a large campground, making it a popular choice for multi-day excursions. Calaway Park operates seasonally from May to October and remains true to its roots as a traditional amusement park despite modern additions.",
      es: "Calaway Park en Calgary, Alberta, es el principal parque de atracciones del oeste canadiense. Inaugurado en 1982, se extiende sobre 40 hectáreas y ofrece más de 30 atracciones, incluyendo montañas rusas, carruseles y una atracción de troncos acuáticos. El parque también ofrece entretenimiento en vivo, juegos y restaurantes. Abre por temporadas, de mayo a octubre, y atrae a más de 400.000 visitantes al año. La entrada incluye acceso a todas las atracciones mecánicas.",
      pt: "O Calaway Park em Calgary, Alberta, é o maior parque de diversões do oeste do Canadá. Inaugurado em 1982, o parque abrange 40 hectares e oferece mais de 30 brinquedos e atrações, incluindo montanhas-russas, carrosséis e uma corredeira. O parque também conta com entretenimento ao vivo, jogos e restaurantes. É aberto sazonalmente de maio a outubro e atrai mais de 400.000 visitantes por ano. A entrada inclui todos os brinquedos.",
      fr: "Calaway Park à Calgary, en Alberta, est le plus grand parc d'attractions de l'Ouest canadien. Ouvert en 1982, il s'étend sur 40 hectares et propose plus de 30 manèges et attractions, dont des montagnes russes, des carrousels et une rivière sauvage. Le parc propose également des spectacles, des jeux et des restaurants. Il est ouvert de mai à octobre et accueille plus de 400 000 visiteurs par an. Le prix d'entrée inclut l'accès illimité aux manèges.",
    },
    factsAdvanced: {
      de: ["Der Park wurde 1982 auf einer Fläche von 160 Hektar eröffnet.", "Es gibt 32 Fahrgeschäfte für verschiedene Adrenalinlevel.", "Der Name \"Calaway\" leitet sich von \"Calgary\" und \"Away\" ab.", "Die Achterbahn \"The Vortex\" ist eine der Hauptattraktionen.", "Der Park verfügt über ein 3D-Kino und einen eigenen RV-Park.", "Über 500.000 Besucher besuchen den Park pro Saison."],
      hu: ["A parkot 1982-ben nyitották meg 160 hektáros területen.", "32 különböző adrenalin-szintű játék várja a látogatókat.", "A \"Calaway\" név a \"Calgary\" és az \"Away\" szavakból származik.", "A \"The Vortex\" hullámvasút a park egyik fő attrakciója.", "A park rendelkezik 3D mozival és saját lakóautó-parkolóval is.", "Szezononként több mint 500 000 látogató keresi fel a parkot."],
      ro: ["Parcul a fost deschis în 1982 pe o suprafață de 160 de hectare.", "Există 32 de atracții mecanice pentru diferite niveluri de adrenalină.", "Numele \"Calaway\" provine din combinarea cuvintelor \"Calgary\" și \"Away\".", "Roller coaster-ul \"The Vortex\" este una dintre atracțiile principale.", "Parcul dispune de un cinematograf 3D și de un parc propriu pentru rulote.", "Peste 500.000 de vizitatori vizitează parcul în fiecare sezon."],
      en: ["The park opened in 1982 on a 160-acre site.", "There are 32 rides catering to various thrill levels.", "The name \"Calaway\" is a blend of \"Calgary\" and \"Away.\"", "The \"Vortex\" roller coaster is one of the park's signature attractions.", "The park features a 3D theater and its own RV park.", "Over 500,000 guests visit the park per operating season."],
      es: ["Apertura: 1982", "Superficie: 40 hectáreas", "Número de atracciones: más de 30", "Visitantes anuales: más de 400.000", "Temporada: mayo a octubre", "Montaña rusa más alta: 30 m"],
      pt: ["Abertura: 1982", "Área: 40 hectares", "Número de atrações: mais de 30", "Visitantes anuais: mais de 400.000", "Temporada: maio a outubro", "Montanha-russa mais alta: 30 m"],
      fr: ["Ouverture : 1982", "Superficie : 40 hectares", "Nombre d'attractions : plus de 30", "Visiteurs annuels : plus de 400 000", "Saison : mai à octobre", "Plus hautes montagnes russes : 30 m"],
    },
